const $=s=>document.querySelector(s);
const theme=$('#theme');
let savedTheme;try{savedTheme=localStorage.getItem('ras-theme')}catch{}
function setTheme(value){document.documentElement.dataset.theme=value;theme.setAttribute('aria-pressed',String(value==='light'));theme.setAttribute('aria-label',value==='dark'?'切换到浅色主题':'切换到深色主题');document.querySelector('meta[name=theme-color]').content=value==='dark'?'#12131f':'#eeebf4'}
setTheme(savedTheme==='light'?'light':'dark');theme.onclick=()=>{const value=document.documentElement.dataset.theme==='dark'?'light':'dark';setTheme(value);try{localStorage.setItem('ras-theme',value)}catch{}};
const modal=$('#modal');function show(content){$('#modal-content').innerHTML=content;modal.showModal()}$('.close-modal').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});
const posts=[['第一夜 / 夜间手记','初めて夜に一人で外に出た。','assets/manga-page-11.jpg'],['片段收藏 / よふかしのうた','今日に満足できるまで、夜ふかししてみろよ。','assets/manga-page-6.jpg']];
document.querySelectorAll('[data-post]').forEach(b=>b.onclick=()=>{const p=posts[Number(b.dataset.post)];show(`<span class="mini-label">${p[0]}</span><h2>${p[1]}</h2><img src="${p[2]}" alt="原漫画试读画面"><p>《彻夜之歌》台词收藏 · 随笔占位</p>`)});
$('#work').onclick=()=>show('<span class="mini-label">NIGHT FRAGMENTS / 001</span><h2>夜间切片</h2><img src="assets/anime-vending-visual.jpg" alt="动画官方售货机主题原图"><p>《彻夜之歌》动画官方售货机视觉 · 场景收藏</p>');
$('#credits').onclick=()=>show('<span class="mini-label">ARTWORK & SOURCES</span><h2>属于夜晚的画面</h2><p>立绘与表情图：<a href="https://yofukashi-no-uta.com/1st/character/#/nazuna" target="_blank" rel="noopener noreferrer">《彻夜之歌》动画官方角色页 ↗</a><br>漫画场景：<a href="https://shogakukan-comic.jp/book?isbn=9784091294920" target="_blank" rel="noopener noreferrer">小学馆第一卷公开试读 ↗</a></p><p>首页售货机背景：<a href="https://yofukashi-no-uta.com/1st/news/archives/24" target="_blank" rel="noopener noreferrer">动画官方「七草ナズナ」主题视觉 ↗</a>（原图场景裁切）</p><p>全身角色：莺馅子来自动画第二季官方角色图；七草荠以官方售货机视觉为参考进行去背景处理。</p><p>漫画 © コトヤマ／小学館<br>动画 ©2022 コトヤマ・小学館／「よふかしのうた」製作委員会</p><p>音乐：Creepy Nuts。两季 OP / ED 使用富士电视台动画官方频道发布的无字幕片头片尾视频，通过 YouTube 官方播放器播放。</p>');
let toastTimer;function toast(text){$('.toast').textContent=text;$('.toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('.toast').classList.remove('visible'),3000)}document.querySelectorAll('[data-social]').forEach(b=>b.onclick=()=>toast(`${b.dataset.social} 联系方式尚未填写`));
const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){document.querySelectorAll('.header nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+e.target.id))}})},{rootMargin:'-15% 0px -50% 0px'});document.querySelectorAll('#home,#about,#notes,#works,#comments,#contact').forEach(s=>observer.observe(s));
let lastStar=0;document.addEventListener('pointermove',e=>{if(e.pointerType==='touch'||matchMedia('(prefers-reduced-motion: reduce)').matches||Date.now()-lastStar<90)return;lastStar=Date.now();const s=document.createElement('span');s.className='cursor-star';s.textContent='✧';s.style.left=e.clientX+'px';s.style.top=e.clientY+'px';document.body.append(s);s.addEventListener('animationend',()=>s.remove())});
